  point_type BIGINT PRIMARY KEY,  -- The point type BIGINT
  description VARCHAR(255) NOT NULL,  -- A description for each point type (e.g., 'Thumb Up', 'Post Main Article')
  points BIGINT NOT NULL  -- The BIGINT of points associated with each action
);

