CREATE TABLE activity_points (
  point_pk BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,  -- Auto-incremented primary key
  user_pk BIGINT NOT NULL,  -- Foreign key to the user who received the points
  points BIGINT NOT NULL,  -- Points awarded for the action
  point_type BIGINT NOT NULL,  -- Type of point (represented as a BIGINT)
  reason VARCHAR(255) NOT NULL,  -- Description of the action (e.g., 'Thumb up', 'Post main article')
  related_pk BIGINT,  -- Foreign key to the relevant table (blog_ratings, blogs, etc.)
  action_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  -- Timestamp for when the activity occurred
  FOREIGN KEY (user_pk) REFERENCES users(user_pk),  -- Foreign key to the users table
  FOREIGN KEY (point_type) REFERENCES point_types(point_type)  -- Foreign key to point_types
);

